"""Code-native editorial SVG illustrations; no third-party or event imagery."""
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'public' / 'images'
OUT.mkdir(parents=True, exist_ok=True)
ink='#201e1d'; blue='#006786'; pink='#aa0b56'

def svg(name, title, subtitle, body, magenta=False):
    accent = pink if magenta else blue
    bg = '#e8d8de' if magenta else '#d6e5e6'
    text=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 400" role="img" aria-labelledby="title"><title id="title">{title} — editorial illustration</title><defs><pattern id="dots" width="6" height="6" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".65" fill="{ink}" opacity=".16"/></pattern></defs><path fill="{bg}" d="M0 0h720v400H0z"/><path fill="url(#dots)" d="M0 0h720v400H0z"/><circle cx="646" cy="42" r="220" fill="{accent}" opacity=".055"/><g stroke="{accent}" stroke-width="1" opacity=".5"><path d="M24 34h20m-10-10v20M676 366h20m-10-10v20"/></g><text x="44" y="55" fill="{accent}" font-family="Georgia,serif" font-size="12" letter-spacing="2">THE FACTCHECK EDITION</text>{body}<text x="44" y="333" fill="{ink}" font-family="Georgia,serif" font-size="34" letter-spacing="-1">{title}</text><text x="46" y="359" fill="{accent}" font-family="Georgia,serif" font-size="11" letter-spacing="2">{subtitle}</text><text x="676" y="55" text-anchor="end" fill="{accent}" font-family="Georgia,serif" font-size="11">2026 / DEMO</text></svg>'''
    (OUT/f'{name}.svg').write_text(text)

bars=''.join(f'<path d="M{x} {180-h}v{h*2}" stroke="{blue}" stroke-width="5" opacity="{.5+(i%3)*.2}"/>' for i,(x,h) in enumerate(zip(range(200,607,13),[12,20,32,15,42,65,48,24,38,76,95,72,48,23,60,83,55,38,22,54,69,41,26,15,42,63,32,24,16,27,12,8])))
svg('audio','A voice. A question.','SOURCE / CONTEXT / EVIDENCE',f'<path d="M44 181h620" stroke="{blue}" stroke-width="1" opacity=".25"/>{bars}<g transform="translate(96 130)" fill="none" stroke="{blue}" stroke-width="4"><rect x="17" y="0" width="36" height="72" rx="18" fill="#f3f2f2"/><path d="M5 48v8a30 30 0 0 0 60 0v-8M35 86v21m-18 0h36"/></g><circle cx="410" cy="180" r="96" fill="none" stroke="{pink}" stroke-width="2" opacity=".45"/>')
svg('ballot','Every vote, in context.','LOOK CLOSER / CHECK THE SOURCE',f'<g transform="translate(320 57) rotate(-12 100 130)"><rect x="10" y="9" width="158" height="190" fill="{pink}" opacity=".18"/><rect x="0" y="0" width="158" height="190" fill="#f3f2f2" stroke="{blue}" stroke-width="2"/><g fill="none" stroke="{blue}" stroke-width="2"><path d="M25 44h105M25 59h68M25 84h105"/><circle cx="45" cy="121" r="16"/><circle cx="111" cy="121" r="16"/></g><path d="m101 121 8 9 16-23" stroke="{pink}" stroke-width="5" fill="none"/></g><path d="m275 228 174-10 75 36-181 21Z" fill="#9fbabc" stroke="{blue}" stroke-width="2"/><path d="m343 275 181-21v38H343Z" fill="{blue}" opacity=".65"/><path d="m275 228 68 47v17h-68Z" fill="{blue}" opacity=".9"/><path d="m334 244 93-6" stroke="{ink}" stroke-width="5"/>')
svg('phone','Pause before you share.','A MESSAGE IS NOT A SOURCE',f'<g transform="translate(435 72) rotate(10 60 105)"><rect x="0" y="0" width="133" height="207" rx="12" fill="{pink}" opacity=".18"/><rect x="-10" y="-6" width="133" height="207" rx="12" fill="#f3f2f2" stroke="{pink}" stroke-width="3"/><path d="M25 10h60M43 181h24" stroke="{pink}" stroke-width="4"/><rect x="7" y="38" width="100" height="95" rx="3" fill="#e8d8de"/><text x="57" y="102" text-anchor="middle" fill="{pink}" font-family="Georgia,serif" font-size="64">?</text></g><path d="M120 125h155v72h-89l-25 22v-22h-41Z" fill="#f3f2f2" stroke="{pink}" stroke-width="2"/><path d="M143 148h108M143 167h70" stroke="{pink}" stroke-width="3"/><path d="m304 162 86-7m-15-10 17 10-15 12" fill="none" stroke="{pink}" stroke-width="2" stroke-dasharray="5 4"/>',True)
svg('network','Follow the information.','TRACE / COMPARE / UNDERSTAND',f'<g stroke="{blue}" stroke-width="1.5" opacity=".65"><path d="m163 169 122-64 105 79 136-83 77 119-213-36-105 69-122-84 227 15m-105-79v148m105-69 114 101m22-184-22 184"/></g>'+''.join(f'<circle cx="{x+4}" cy="{y+3}" r="{r}" fill="{pink}" opacity=".2"/><circle cx="{x}" cy="{y}" r="{r}" fill="#f3f2f2" stroke="{blue}" stroke-width="2"/>' for x,y,r in [(163,169,18),(285,105,25),(390,184,40),(526,101,21),(603,220,17),(285,253,21),(504,285,12)])+f'<g fill="none" stroke="{blue}" stroke-width="2"><circle cx="390" cy="179" r="17"/><path d="m402 192 14 14"/></g>')
svg('document','Read beyond the headline.','THE COMPLETE PICTURE MATTERS',f'<g transform="translate(310 70) rotate(-8 100 100)"><path d="M10 10h245v199H10Z" fill="{pink}" opacity=".13"/><path d="M0 0h245v199H0Z" fill="#f3f2f2" stroke="{blue}" stroke-width="2"/><path d="M25 35h190M25 52h140M25 72h190" stroke="{blue}" stroke-width="4"/><path d="M25 105h83v57H25Z" fill="#c7ddde"/><path d="M126 104h87m-87 20h87m-87 20h65M25 181h190" stroke="{blue}" stroke-width="2"/><circle cx="195" cy="141" r="39" stroke="{pink}" stroke-width="3" fill="none"/><path d="m224 169 26 28" stroke="{pink}" stroke-width="8"/></g>')
svg('chart','What do the numbers say?','ASK ABOUT THE DENOMINATOR',f'<path d="M249 91v181h341" fill="none" stroke="{pink}" stroke-width="2"/><path d="M276 206h42v66h-42Zm76-46h42v112h-42Zm76-48h42v160h-42Zm76 69h42v91h-42Z" fill="{pink}" opacity=".45"/><path d="M257 136h325M257 182h325M257 227h325" stroke="{pink}" stroke-dasharray="3 5" opacity=".3"/><text x="112" y="215" font-family="Georgia,serif" font-size="100" fill="{pink}">%</text>',True)
svg('message','Where did this come from?','FICTIONAL MESSAGE / FOR DEMONSTRATION',f'<rect x="150" y="87" width="420" height="181" rx="4" fill="#f3f2f2" stroke="{blue}" stroke-width="2"/><circle cx="186" cy="119" r="12" fill="#c7ddde"/><path d="M211 115h139M211 129h84" stroke="{blue}" stroke-width="3"/><path d="M177 159h362M177 181h316M177 203h275" stroke="{blue}" stroke-width="2" opacity=".55"/><text x="178" y="243" fill="{pink}" font-family="Georgia,serif" font-size="13" letter-spacing="2">SOURCE: UNVERIFIED</text>')
(ROOT/'public'/'favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect width="100" height="100" rx="12" fill="#f3f2f2"/><g stroke="#201e1d" fill="none" stroke-width="5"><circle cx="50" cy="50" r="43"/><ellipse cx="50" cy="50" rx="30" ry="19"/></g><circle cx="50" cy="50" r="10" fill="#201e1d"/></svg>')
print('Wrote 8 local SVG assets.')
